export const FIELD_ORDER = ['firstName', 'lastName', 'dateOfBirth', 'gender'];

const NAME_PATTERN = /^[A-Za-z][A-Za-z\s'-]*$/;
const EMAIL_PATTERN = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i;
const US_PHONE_PATTERN = /^\+1 \(\d{3}\) \d{3}-\d{4}$/;

export const validateEmail = (value = '') => {
  const trimmed = String(value).trim();

  if (!trimmed) return 'Please enter your email address.';
  if (!EMAIL_PATTERN.test(trimmed)) return 'Please enter a valid email address.';

  return '';
};

export const validatePhone = (value = '') => {
  const trimmed = String(value).trim();

  if (!trimmed) return 'Please enter your phone number.';
  if (!US_PHONE_PATTERN.test(trimmed)) return 'Please enter a valid U.S. phone number in the format +1 (xxx) xxx-xxxx.';

  return '';
};

export const validateField = (fieldName, value = '', formData = {}) => {
  const trimmed = typeof value === 'string' ? value.trim() : '';

  switch (fieldName) {
    case 'firstName':
      if (!trimmed) return 'Please enter your first name.';
      if (trimmed.length < 2) return 'Name must be at least 2 characters.';
      if (!NAME_PATTERN.test(trimmed)) return 'Name can only contain letters, spaces, and hyphens.';
      return '';

    case 'lastName':
      if (!trimmed) return 'Please enter your last name.';
      if (trimmed.length < 2) return 'Name must be at least 2 characters.';
      if (!NAME_PATTERN.test(trimmed)) return 'Name can only contain letters, spaces, and hyphens.';
      return '';

    case 'dateOfBirth':
      if (!trimmed) return 'Please enter your date of birth.';
      if (!/^\d{2}\/\d{2}\/\d{4}$/.test(trimmed)) return 'Please enter a valid date in MM/DD/YYYY format.';

      const [month, day, year] = trimmed.split('/').map(Number);
      const date = new Date(year, month - 1, day);

      if (
        Number.isNaN(date.getTime()) ||
        date.getFullYear() !== year ||
        date.getMonth() !== month - 1 ||
        date.getDate() !== day
      ) {
        return 'Please enter a valid date in MM/DD/YYYY format.';
      }

      const today = new Date();
      let age = today.getFullYear() - year;
      const monthDiff = today.getMonth() - (month - 1);

      if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < day)) {
        age -= 1;
      }

      if (age < 0 || age > 120) {
        return 'Please enter an age between 0 and 120 years.';
      }

      return '';

    case 'gender':
      if (!trimmed) return 'Please select your gender.';
      return '';

    case 'email':
      return validateEmail(value);

    case 'phone':
      return validatePhone(value);

    default:
      return '';
  }
};

export const validateForm = (formData = {}) => {
  const errors = {};

  FIELD_ORDER.forEach((fieldName) => {
    errors[fieldName] = validateField(fieldName, formData[fieldName], formData);
  });

  return {
    errors,
    isValid: Object.values(errors).every((error) => !error),
  };
};
